public class Main {
    static boolean isArmstrong(int n) {
        int digits = String.valueOf(n).length();
        int sum = 0;
        int rest = n;
        while (rest > 0) {
            int d = rest % 10;
            int power = 1;
            for (int i = 0; i < digits; i++) {
                power *= d;
            }
            sum += power;
            rest /= 10;
        }
        return sum == n;
    }

    public static void main(String[] args) {
        for (int n = 100; n < 1000; n++) {
            if (isArmstrong(n)) {
                System.out.println(n);
            }
        }
    }
}
